// Input: signer, method, args, ownerId, jobId, amount (USDC, decimal)
const i = $input.first().json;
const SIGNERS = ['tx-buyer', 'tx-seller', 'guardian-buyer',
                 'reviewer-1', 'reviewer-2', 'reviewer-3', 'platform'];
if (!SIGNERS.includes(i.signer)) throw new Error('Unknown signer: ' + i.signer);
if (!/^[a-z_]+$/.test(i.method || '')) throw new Error('Bad method name: ' + i.method);
return [{
  json: {
    signer: i.signer,
    signerIndex: SIGNERS.indexOf(i.signer),
    signerAccount: i.cfg.accounts[i.signer] || i.signer,
    method: i.method,
    args: i.args || {},
    ownerId: i.ownerId || null,
    jobId: i.jobId || null,
    amount: i.amount ?? null,
    mode: i.cfg.mode === 'testnet' ? 'testnet' : 'mock',
    contractId: i.cfg.contractId,
  },
}];

