// Pretends to be the contract: same checks, same refusals (paper Table 5).
const v = $('Validate input').first().json;
const m = $input.first().json || {};
const TX = ['post_job', 'place_bid', 'accept_offer', 'fund_job', 'submit_delivery', 'vote'];
const KEYS = {
  'tx-buyer': TX, 'tx-seller': TX, 'guardian-buyer': ['pause'],
  'reviewer-1': ['vote'], 'reviewer-2': ['vote'], 'reviewer-3': ['vote'],
  platform: ['release_expired', 'flag_risk'],
};
const fail = (rejectedBy, error) => [{ json: { ok: false, rejectedBy, error } }];
const n = (x) => Number(x ?? 0);

// 1) What the function-call key itself allows (protocol level)
if (!KEYS[v.signer].includes(v.method)) {
  return fail('protocol:MethodNameMismatch', `Key ${v.signer} may not call ${v.method}`);
}
// 2) Pause stops every money-moving call
const moving = ['post_job', 'place_bid', 'accept_offer', 'fund_job', 'submit_delivery'];
if (moving.includes(v.method) && m.paused === true) {
  return fail('contract:paused', 'Agents are paused by the owner or the guardian');
}
// 3) Mandate checks on funding
if (v.method === 'fund_job') {
  const price = n(m.agreed_price ?? v.amount);
  const amount = n(v.amount ?? price);
  if (m.per_job_cap != null && price > n(m.per_job_cap)) {
    return fail('contract:per_job_cap', `Job price ${price} USDC is over the per-job cap of ${n(m.per_job_cap)}`);
  }
  if (m.daily_cap != null && n(m.spent_today) + amount > n(m.daily_cap)) {
    return fail('contract:daily_cap', `Would reach ${n(m.spent_today) + amount} USDC today; daily cap is ${n(m.daily_cap)}`);
  }
  const cats = m.allowed_categories || [];
  if (cats.length && m.category && !cats.includes(m.category)) {
    return fail('contract:category', `Category ${m.category} is not allowed`);
  }
  if (m.price_check === 'held') return fail('contract:price_hold', 'The bid is held by the price check');
  if (n(m.fraud_score) >= 70 && !m.owner_approved_risk) {
    return fail('contract:fraud_flag', `Seller is flagged (score ${m.fraud_score}) and not approved by the owner`);
  }
  if (n(m.settled_jobs) < 3 && m.new_seller_cap != null && price > n(m.new_seller_cap)) {
    return fail('contract:new_seller_cap', `New seller: ${price} USDC is over the starter cap of ${n(m.new_seller_cap)}`);
  }
  if (n(m.available) < amount) return fail('contract:balance', `Free balance ${n(m.available)} USDC is below ${amount}`);
}
const txHash = 'mock-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
return [{ json: { ok: true, txHash } }];

const v = $('Validate input').first().json;
const txId = $('Insert pending tx').first().json.id;
const r = $input.first().json;
let ok, error = null, rejectedBy = null, explorer = null;
const txHash = r.txHash || null;

if (v.mode === 'mock') {
  ok = r.ok === true;
  error = r.error || null;
  rejectedBy = r.rejectedBy || null;
} else {
  ok = Boolean(txHash) && !r.error;
  explorer = r.explorer || null;
  error = r.error || null;
  if (r.status && r.status.Failure) {
    ok = false;
    error = JSON.stringify(r.status.Failure).slice(0, 500);
  }
  if (!ok) {
    const m = String(error || '').match(
      /MethodNameMismatch|ReceiverMismatch|NotEnoughAllowance|DepositWithFunctionCall/i);
    rejectedBy = m ? 'protocol:' + m[0] : 'contract';
  }
}

let effect = 'none';
if (ok && v.mode === 'mock' && v.method === 'fund_job') effect = 'mock-fund';
if (ok && v.mode === 'mock' && v.method === 'pause') effect = 'mock-pause';

return [{
  json: {
    ok, txHash, explorer, error, rejectedBy, txId, effect,
    method: v.method, signer: v.signer, amount: v.amount, ownerId: v.ownerId, jobId: v.jobId,
  },
}];
